/**
 * The native android/ folder is regenerated by `expo prebuild --clean` on every
 * build, so Gradle memory settings must be re-applied here (not committed once).
 *
 * Fixes a release-build OOM ("Java heap space" in :app:mergeReleaseNativeDebugMetadata):
 *  1. Raise the Gradle JVM heap (2 GB default is too small with this many native modules).
 *  2. Skip native debug-symbol merging for release — those symbols are not shipped in
 *     the APK, and that task is the memory hog that was failing on lower-RAM machines.
 */
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const androidRoot = path.join(__dirname, "..", "android");

// 1) Gradle heap
const gradleProps = path.join(androidRoot, "gradle.properties");
if (fs.existsSync(gradleProps)) {
  let text = fs.readFileSync(gradleProps, "utf8");
  const desired = "org.gradle.jvmargs=-Xmx4096m -XX:MaxMetaspaceSize=1024m";
  if (/^org\.gradle\.jvmargs=.*$/m.test(text)) {
    text = text.replace(/^org\.gradle\.jvmargs=.*$/m, desired);
  } else {
    text += `\n${desired}\n`;
  }
  fs.writeFileSync(gradleProps, text);
  console.log("Gradle heap set to 4096m for the release build.");
} else {
  console.warn("gradle.properties not found — run expo prebuild first.");
}

// 2) Skip native debug-symbol merge for release
const appGradle = path.join(androidRoot, "app", "build.gradle");
if (fs.existsSync(appGradle)) {
  let text = fs.readFileSync(appGradle, "utf8");
  if (!text.includes("debugSymbolLevel")) {
    const anchor = "            def enableShrinkResources";
    if (text.includes(anchor)) {
      text = text.replace(
        anchor,
        "            ndk { debugSymbolLevel 'none' }\n" + anchor
      );
      fs.writeFileSync(appGradle, text);
      console.log("Release native debug-symbol merge disabled (saves memory).");
    } else {
      console.warn("Could not find the release buildType anchor in app/build.gradle.");
    }
  } else {
    console.log("debugSymbolLevel already set — leaving as is.");
  }
} else {
  console.warn("app/build.gradle not found — run expo prebuild first.");
}
